"use strict";(globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init=globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init||[]).push([[92443],{73961(e,a,o){o.r(a),o.d(a,{assets:()=>t,contentTitle:()=>c,default:()=>u,frontMatter:()=>i,metadata:()=>n,toc:()=>l});const n=JSON.parse('{"id":"cursos/cleancode/modulos/funciones/cuestionario","title":"cuestionario","description":"2. [Investigar] \xbfQu\xe9 es el principio \\"Tell, Don\'t Ask\\" y c\xf3mo se relaciona con Command Query Separation m\xe1s all\xe1 de lo que la clase describe? \xbfQu\xe9 objeciones plantea David West (\\"Object Thinking\\") a la separaci\xf3n estricta de comandos y consultas?","source":"@site/docs/cursos/cleancode/modulos/03-funciones/cuestionario.md","sourceDirName":"cursos/cleancode/modulos/03-funciones","slug":"/cursos/cleancode/modulos/funciones/cuestionario","permalink":"/sasf-temarios/cursos/cleancode/modulos/funciones/cuestionario","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"private":true,"sidebar_class_name":"private","sidebar_label":"Cuestionario"},"sidebar":"cursosSidebar","previous":{"title":"Clase","permalink":"/sasf-temarios/cursos/cleancode/modulos/funciones/clase"},"next":{"title":"Ejercicio","permalink":"/sasf-temarios/cursos/cleancode/modulos/funciones/ejercicio"}}');var s=o(74848),r=o(28453);const i={private:!0,sidebar_class_name:"private",sidebar_label:"Cuestionario"},c=void 0,t={},l=[{value:"2. [Investigar] \xbfQu\xe9 es el principio &quot;Tell, Don&#39;t Ask&quot; y c\xf3mo se relaciona con Command Query Separation m\xe1s all\xe1 de lo que la clase describe? \xbfQu\xe9 objeciones plantea David West (&quot;Object Thinking&quot;) a la separaci\xf3n estricta de comandos y consultas?",id:"2-investigar-qu\xe9-es-el-principio-tell-dont-ask-y-c\xf3mo-se-relaciona-con-command-query-separation-m\xe1s-all\xe1-de-lo-que-la-clase-describe-qu\xe9-objeciones-plantea-david-west-object-thinking-a-la-separaci\xf3n-estricta-de-comandos-y-consultas",level:3},{value:"3. [Investigar] \xbfQu\xe9 son las &quot;check-callback closures&quot; de Peter Sommerlad y c\xf3mo se relacionan con el manejo de recursos en funciones? \xbfQu\xe9 patr\xf3n de C++/Java 7 (try-with-resources) resuelve el problema que Sommerlad identific\xf3?",id:"3-investigar-qu\xe9-son-las-check-callback-closures-de-peter-sommerlad-y-c\xf3mo-se-relacionan-con-el-manejo-de-recursos-en-funciones-qu\xe9-patr\xf3n-de-cjava-7-try-with-resources-resuelve-el-problema-que-sommerlad-identific\xf3",level:3},{value:"4. [Investigar] \xbfQu\xe9 es la regla de los &quot;siete m\xe1s o menos dos&quot; de George Miller (1956) en psicolog\xeda cognitiva, y c\xf3mo la aplican autores como Steve McConnell al n\xfamero aceptable de par\xe1metros y niveles de anidamiento en funciones?",id:"4-investigar-qu\xe9-es-la-regla-de-los-siete-m\xe1s-o-menos-dos-de-george-miller-1956-en-psicolog\xeda-cognitiva-y-c\xf3mo-la-aplican-autores-como-steve-mcconnell-al-n\xfamero-aceptable-de-par\xe1metros-y-niveles-de-anidamiento-en-funciones",level:3},{value:"5. [Conectar] La clase recomienda usar polimorfismo en lugar de switch statements. \xbfQu\xe9 plantea el libro &quot;Refactoring&quot; de Martin Fowler sobre el refactoring &quot;Replace Conditional with Polymorphism&quot;? \xbfEn qu\xe9 casos espec\xedficos Fowler ADVIERTE que este refactoring es contraproducente?",id:"5-conectar-la-clase-recomienda-usar-polimorfismo-en-lugar-de-switch-statements-qu\xe9-plantea-el-libro-refactoring-de-martin-fowler-sobre-el-refactoring-replace-conditional-with-polymorphism-en-qu\xe9-casos-espec\xedficos-fowler-advierte-que-este-refactoring-es-contraproducente",level:3},{value:"6. [Conectar] La clase describe DRY (Don&#39;t Repeat Yourself) con un ejemplo de c\xf3digo duplicado de logging. \xbfC\xf3mo se relaciona DRY con el concepto de &quot;Orthogonality&quot; (ortogonalidad) de &quot;The Pragmatic Programmer&quot;? \xbfQu\xe9 distingue la duplicaci\xf3n accidental de la duplicaci\xf3n esencial?",id:"6-conectar-la-clase-describe-dry-dont-repeat-yourself-con-un-ejemplo-de-c\xf3digo-duplicado-de-logging-c\xf3mo-se-relaciona-dry-con-el-concepto-de-orthogonality-ortogonalidad-de-the-pragmatic-programmer-qu\xe9-distingue-la-duplicaci\xf3n-accidental-de-la-duplicaci\xf3n-esencial",level:3},{value:"7. [Conectar] La clase menciona la &quot;Stepdown Rule&quot; para ordenar funciones. \xbfC\xf3mo se relaciona con el &quot;Newspaper Metaphor&quot; del m\xf3dulo 04? \xbfQu\xe9 dice Robert Martin en &quot;Clean Architecture&quot; sobre c\xf3mo la Stepdown Rule se aplica a nivel de M\xd3DULOS y no solo de archivos?",id:"7-conectar-la-clase-menciona-la-stepdown-rule-para-ordenar-funciones-c\xf3mo-se-relaciona-con-el-newspaper-metaphor-del-m\xf3dulo-04-qu\xe9-dice-robert-martin-en-clean-architecture-sobre-c\xf3mo-la-stepdown-rule-se-aplica-a-nivel-de-m\xf3dulos-y-no-solo-de-archivos",level:3},{value:"8. [Cuestionar] La clase dice que las funciones &quot;deben ser peque\xf1as&quot; (20 l\xedneas o menos). John Ousterhout, en &quot;A Philosophy of Software Design&quot;, argumenta que este enfoque produce &quot;shallow modules&quot;. \xbfEn qu\xe9 consiste su cr\xedtica y qu\xe9 evidencia emp\xedrica existe a favor y en contra de las funciones peque\xf1as?",id:"8-cuestionar-la-clase-dice-que-las-funciones-deben-ser-peque\xf1as-20-l\xedneas-o-menos-john-ousterhout-en-a-philosophy-of-software-design-argumenta-que-este-enfoque-produce-shallow-modules-en-qu\xe9-consiste-su-cr\xedtica-y-qu\xe9-evidencia-emp\xedrica-existe-a-favor-y-en-contra-de-las-funciones-peque\xf1as",level:3},{value:"9. [Cuestionar] El principio &quot;Command Query Separation&quot; dice que un m\xe9todo debe ser comando o consulta. Sin embargo, operaciones como <code>stack.pop()</code> \u2014que devuelve el elemento y modifica el stack\u2014 son ubicuas en la pr\xe1ctica. \xbfEs <code>pop()</code> un mal dise\xf1o? \xbfQu\xe9 dice Bertrand Meyer (creador de CQS) sobre este tipo de excepciones?",id:"9-cuestionar-el-principio-command-query-separation-dice-que-un-m\xe9todo-debe-ser-comando-o-consulta-sin-embargo-operaciones-como-stackpop-que-devuelve-el-elemento-y-modifica-el-stack-son-ubicuas-en-la-pr\xe1ctica-es-pop-un-mal-dise\xf1o-qu\xe9-dice-bertrand-meyer-creador-de-cqs-sobre-este-tipo-de-excepciones",level:3},{value:"10. [Cuestionar] &quot;Extraer hasta que no puedas extraer m\xe1s&quot; es una filosof\xeda de refactorizaci\xf3n atribuida a Robert C. Martin. \xbfQu\xe9 l\xedmites identifica Sandi Metz (&quot;99 Bottles of OOP&quot;) al &quot;extract method&quot; agresivo? \xbfC\xf3mo determina ella cu\xe1ndo una extracci\xf3n est\xe1 creando una abstracci\xf3n equivocada?",id:"10-cuestionar-extraer-hasta-que-no-puedas-extraer-m\xe1s-es-una-filosof\xeda-de-refactorizaci\xf3n-atribuida-a-robert-c-martin-qu\xe9-l\xedmites-identifica-sandi-metz-99-bottles-of-oop-al-extract-method-agresivo-c\xf3mo-determina-ella-cu\xe1ndo-una-extracci\xf3n-est\xe1-creando-una-abstracci\xf3n-equivocada",level:3}];function d(e){const a={code:"code",h3:"h3",hr:"hr",p:"p",strong:"strong",...(0,r.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(a.h3,{id:"2-investigar-qu\xe9-es-el-principio-tell-dont-ask-y-c\xf3mo-se-relaciona-con-command-query-separation-m\xe1s-all\xe1-de-lo-que-la-clase-describe-qu\xe9-objeciones-plantea-david-west-object-thinking-a-la-separaci\xf3n-estricta-de-comandos-y-consultas",children:'2. [Investigar] \xbfQu\xe9 es el principio "Tell, Don\'t Ask" y c\xf3mo se relaciona con Command Query Separation m\xe1s all\xe1 de lo que la clase describe? \xbfQu\xe9 objeciones plantea David West ("Object Thinking") a la separaci\xf3n estricta de comandos y consultas?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),': El principio "Tell, Don\'t Ask" (Alec Sharp, Smalltalk community, popularizado en "The Pragmatic Programmer" de Hunt & Thomas, 1999) dice que en lugar de preguntar a un objeto por su estado y decidir qu\xe9 hacer, le digas al objeto QU\xc9 hacer y dejes que \xe9l decida. CQS (Bertrand Meyer) dice: un m\xe9todo debe ser comando o consulta. La intersecci\xf3n es: una consulta que se usa SOLO para decidir un comando es una violaci\xf3n de Tell Don\'t Ask. Por ejemplo: ',(0,s.jsx)(a.code,{children:"if (user.getStatus() == ACTIVE) &#x7B; user.activate(); &#x7D;"})," pregunta y decide afuera; ",(0,s.jsx)(a.code,{children:"user.tryActivate()"}),' encapsula la decisi\xf3n. David West, en "Object Thinking" (2004), critica la separaci\xf3n estricta de CQS desde la filosof\xeda original de objetos de Alan Kay: los objetos son "computadoras en una red" que se comunican por mensajes. En Smalltalk, un mensaje puede hacer AMBAS cosas y es natural. West argumenta que CQS es un invento de lenguajes procedurales disfrazados de OOP (como Java y C++) y que Smalltalk, Ruby o lenguajes puramente orientados a objetos no necesitan esa separaci\xf3n.']}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),': La clase presenta CQS como regla absoluta sin explorar su origen (Meyer, lenguaje Eiffel, orientado a contratos) ni sus cr\xedticas. West es un autor fundamental en teor\xeda de objetos que cuestiona los "principios" de Clean Code como Java-c\xe9ntricos. El alumno debe entender que CQS es una buena heur\xedstica en lenguajes con efectos secundarios no controlados, pero no un principio universal del dise\xf1o de software.']}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"3-investigar-qu\xe9-son-las-check-callback-closures-de-peter-sommerlad-y-c\xf3mo-se-relacionan-con-el-manejo-de-recursos-en-funciones-qu\xe9-patr\xf3n-de-cjava-7-try-with-resources-resuelve-el-problema-que-sommerlad-identific\xf3",children:'3. [Investigar] \xbfQu\xe9 son las "check-callback closures" de Peter Sommerlad y c\xf3mo se relacionan con el manejo de recursos en funciones? \xbfQu\xe9 patr\xf3n de C++/Java 7 (try-with-resources) resuelve el problema que Sommerlad identific\xf3?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),': Peter Sommerlad, en su trabajo sobre simplicidad y seguridad en c\xf3digo (C++ Report, 1998-2000), identific\xf3 que el patr\xf3n de funciones que adquieren un recurso (archivo, lock, conexi\xf3n) y requieren que el llamante recuerde liberarlo es inherentemente fr\xe1gil. Propuso las "check-callback closures": en lugar de retornar el recurso al llamante, la funci\xf3n que adquiere el recurso ejecuta un callback y libera el recurso autom\xe1ticamente. Esto evolucion\xf3 en C++ al patr\xf3n RAII (Resource Acquisition Is Initialization, Bjarne Stroustrup) y en Java 7 al try-with-resources con ',(0,s.jsx)(a.code,{children:"AutoCloseable"}),'. La conexi\xf3n con Clean Code: cuando una funci\xf3n hace try-catch-finally para liberar recursos, esos recursos deber\xedan ser gestionados por una funci\xf3n/clase separada que implemente el patr\xf3n de adquisici\xf3n-liberaci\xf3n segura. No es solo "funciones peque\xf1as", es "funciones que no mezclan l\xf3gica de negocio con gesti\xf3n de recursos".']}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase habla de try-catch-finally como \xe1mbito de transacci\xf3n, pero no desarrolla el patr\xf3n de gesti\xf3n de recursos. Sommerlad influy\xf3 en el dise\xf1o de Resource Management en m\xfaltiples lenguajes y su trabajo conecta Clean Code con seguridad de memoria y correcci\xf3n de programas m\xe1s all\xe1 de la mera legibilidad."]}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"4-investigar-qu\xe9-es-la-regla-de-los-siete-m\xe1s-o-menos-dos-de-george-miller-1956-en-psicolog\xeda-cognitiva-y-c\xf3mo-la-aplican-autores-como-steve-mcconnell-al-n\xfamero-aceptable-de-par\xe1metros-y-niveles-de-anidamiento-en-funciones",children:'4. [Investigar] \xbfQu\xe9 es la regla de los "siete m\xe1s o menos dos" de George Miller (1956) en psicolog\xeda cognitiva, y c\xf3mo la aplican autores como Steve McConnell al n\xfamero aceptable de par\xe1metros y niveles de anidamiento en funciones?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),': George Miller public\xf3 "The Magical Number Seven, Plus or Minus Two" (1956, Psychological Review), demostrando que la memoria de trabajo humana puede manejar aproximadamente 7 \xb1 2 \xedtems simult\xe1neamente. Steve McConnell, en "Code Complete 2" (2004), aplica este l\xedmite a: (a) n\xfamero de par\xe1metros de una funci\xf3n (7 m\xe1ximo, aunque Clean Code es m\xe1s estricto con 3), (b) niveles de anidamiento de bloques (3-4 m\xe1ximo), (c) n\xfamero de variables locales vivas simult\xe1neamente en un scope, (d) n\xfamero de pasos conceptuales en un m\xe9todo. McConnell argumenta que este l\xedmite cognitivo \u2014no una preferencia est\xe9tica\u2014 es la RA\xcdZ de por qu\xe9 las funciones largas son dif\xedciles: cuando un desarrollador lee una funci\xf3n de 100 l\xedneas con 15 variables locales y 8 niveles de if, su memoria de trabajo se satura y la comprensi\xf3n colapsa. Los 3 par\xe1metros de Clean Code son un l\xedmite m\xe1s conservador que 7, y se justifica porque adem\xe1s de MEMORIZAR los par\xe1metros, el lector debe RAZONAR sobre sus interacciones.']}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase da l\xedmites num\xe9ricos (3 par\xe1metros, 20 l\xedneas) pero sin explicar su origen cognitivo. Miller es una de las citas m\xe1s importantes de la psicolog\xeda del siglo XX y fundamenta CIENT\xcdFICAMENTE las reglas de Clean Code. El alumno que investiga a McConnell y Miller puede justificar Clean Code no como dogma sino como ergonom\xeda cognitiva."]}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"5-conectar-la-clase-recomienda-usar-polimorfismo-en-lugar-de-switch-statements-qu\xe9-plantea-el-libro-refactoring-de-martin-fowler-sobre-el-refactoring-replace-conditional-with-polymorphism-en-qu\xe9-casos-espec\xedficos-fowler-advierte-que-este-refactoring-es-contraproducente",children:'5. [Conectar] La clase recomienda usar polimorfismo en lugar de switch statements. \xbfQu\xe9 plantea el libro "Refactoring" de Martin Fowler sobre el refactoring "Replace Conditional with Polymorphism"? \xbfEn qu\xe9 casos espec\xedficos Fowler ADVIERTE que este refactoring es contraproducente?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),': Martin Fowler, en "Refactoring: Improving the Design of Existing Code" (2da edici\xf3n, 2018), describe el refactoring "Replace Conditional with Polymorphism" (Cap\xedtulo 10). La mec\xe1nica: ten\xe9s un switch/if que decide comportamiento seg\xfan tipo; cre\xe1s subclases y mov\xe9s cada rama a una subclase. Pero Fowler advierte expl\xedcitamente que el refactoring es contraproducente cuando: (1) la variante de comportamiento es TRIVIAL (ej. un descuento de 5% vs 10% \u2014el polimorfismo introduce m\xe1s c\xf3digo boilerplate que la l\xf3gica que modela), (2) la jerarqu\xeda de tipos no es ESTABLE (cada semana se agrega un nuevo tipo y el polimorfismo requerir\xeda modificar una jerarqu\xeda profunda, mientras que un switch agregando una rama es m\xe1s simple), (3) las variantes no comparten una interfaz sem\xe1ntica coherente (si est\xe1s forzando m\xe9todos que no aplican naturalmente a todas las subclases, est\xe1s en camino al Refused Bequest smell). Fowler tambi\xe9n introduce el concepto de "variabilizaci\xf3n": antes de reemplazar con polimorfismo, preguntate cu\xe1ntas VARIABLES (no solo cu\xe1ntos tipos) determinan el comportamiento.']}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),': La clase presenta el polimorfismo como soluci\xf3n universal a los switch. Fowler \u2014el propio autor de los code smells que la clase cita\u2014 es m\xe1s matizado. El alumno debe aprender que TODO refactoring es contextual y que incluso las "buenas pr\xe1cticas" tienen contraindicaciones. La 2da edici\xf3n de Refactoring (escrita en JavaScript, no Java) es particularmente pragm\xe1tica sobre cu\xe1ndo NO refactorizar.']}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"6-conectar-la-clase-describe-dry-dont-repeat-yourself-con-un-ejemplo-de-c\xf3digo-duplicado-de-logging-c\xf3mo-se-relaciona-dry-con-el-concepto-de-orthogonality-ortogonalidad-de-the-pragmatic-programmer-qu\xe9-distingue-la-duplicaci\xf3n-accidental-de-la-duplicaci\xf3n-esencial",children:'6. [Conectar] La clase describe DRY (Don\'t Repeat Yourself) con un ejemplo de c\xf3digo duplicado de logging. \xbfC\xf3mo se relaciona DRY con el concepto de "Orthogonality" (ortogonalidad) de "The Pragmatic Programmer"? \xbfQu\xe9 distingue la duplicaci\xf3n accidental de la duplicaci\xf3n esencial?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),': Dave Thomas y Andy Hunt, en "The Pragmatic Programmer" (1999), introdujeron DRY Y ortogonalidad como conceptos hermanos. DRY dice que cada pieza de conocimiento debe tener una representaci\xf3n \xfanica e inequ\xedvoca en el sistema. Ortogonalidad dice que dos m\xf3dulos deben ser independientes: cambiar uno no afecta al otro. La conexi\xf3n cr\xedtica es que NO toda duplicaci\xf3n de c\xf3digo es violaci\xf3n de DRY. Thomas y Hunt distinguen: (a) duplicaci\xf3n de CONOCIMIENTO (viola DRY): dos lugares que codifican "el IVA es 21%" \u2014si cambia el IVA, hay que cambiar ambos; (b) duplicaci\xf3n accidental: dos lugares que COINCIDEN en tener c\xf3digo similar pero modelan conceptos distintos (ej. ',(0,s.jsx)(a.code,{children:"validate(Order)"})," y ",(0,s.jsx)(a.code,{children:"validate(Invoice)"})," ambas chequean campos no-nulos, pero las REGLAS de validaci\xf3n son distintas y cambiar\xe1n independientemente). El alumno que unifica ",(0,s.jsx)(a.code,{children:"validate(Order)"})," y ",(0,s.jsx)(a.code,{children:"validate(Invoice)"})," en una sola funci\xf3n ",(0,s.jsx)(a.code,{children:"validate(Entity)"}),' porque "se ve\xedan igual" est\xe1 creando acoplamiento incidental entre conceptos que DEBEN evolucionar independientemente \u2014violando ortogonalidad por obedecer DRY ciegamente.']}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),': La clase muestra DRY como "c\xf3digo repetido = malo". Thomas y Hunt refinaron el concepto d\xe9cadas despu\xe9s de la primera edici\xf3n: la clave es duplicaci\xf3n de CONOCIMIENTO, no de caracteres. Esta distinci\xf3n es crucial porque muchos alumnos aplican DRY sobre-duplicando todo y crean abstracciones incorrectas (el problema del "premature abstraction" que Sandi Metz populariz\xf3).']}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"7-conectar-la-clase-menciona-la-stepdown-rule-para-ordenar-funciones-c\xf3mo-se-relaciona-con-el-newspaper-metaphor-del-m\xf3dulo-04-qu\xe9-dice-robert-martin-en-clean-architecture-sobre-c\xf3mo-la-stepdown-rule-se-aplica-a-nivel-de-m\xf3dulos-y-no-solo-de-archivos",children:'7. [Conectar] La clase menciona la "Stepdown Rule" para ordenar funciones. \xbfC\xf3mo se relaciona con el "Newspaper Metaphor" del m\xf3dulo 04? \xbfQu\xe9 dice Robert Martin en "Clean Architecture" sobre c\xf3mo la Stepdown Rule se aplica a nivel de M\xd3DULOS y no solo de archivos?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),': La Stepdown Rule y el Newspaper Metaphor son el MISMO principio aplicado a distintas escalas: leer de arriba hacia abajo, con la informaci\xf3n m\xe1s importante primero y los detalles despu\xe9s. En "Clean Architecture" (2017), Robert Martin extiende este principio al nivel de M\xd3DULOS (packages, JARs): los m\xf3dulos de alto nivel (pol\xedticas de negocio) deben leerse primero, y los de bajo nivel (infraestructura) despu\xe9s. La dependencia del c\xf3digo fuente debe apuntar HACIA ABAJO en la jerarqu\xeda de abstracci\xf3n, y tambi\xe9n hacia ABAJO en la estructura de directorios. En un proyecto Spring: ',(0,s.jsx)(a.code,{children:"com.empresa.nominas.service.payroll"})," (alto nivel) debe depender de interfaces, no de ",(0,s.jsx)(a.code,{children:"com.empresa.nominas.infrastructure.database"}),' (bajo nivel). Martin llama a esto la "Screaming Architecture": la estructura de directorios DEBE GRITAR cu\xe1l es el negocio de la aplicaci\xf3n, no qu\xe9 frameworks usa.']}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),': La clase presenta la Stepdown Rule como t\xe9cnica de ordenamiento intra-clase. "Clean Architecture" la escala a nivel de sistema, lo cual conecta el m\xf3dulo 03 con los conceptos de arquitectura que el alumno ver\xe1 en el proyecto final. El alumno que investiga descubre que la Stepdown Rule no es solo est\xe9tica: es la manifestaci\xf3n del Dependency Inversion Principle a nivel de estructura de archivos.']}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"8-cuestionar-la-clase-dice-que-las-funciones-deben-ser-peque\xf1as-20-l\xedneas-o-menos-john-ousterhout-en-a-philosophy-of-software-design-argumenta-que-este-enfoque-produce-shallow-modules-en-qu\xe9-consiste-su-cr\xedtica-y-qu\xe9-evidencia-emp\xedrica-existe-a-favor-y-en-contra-de-las-funciones-peque\xf1as",children:'8. [Cuestionar] La clase dice que las funciones "deben ser peque\xf1as" (20 l\xedneas o menos). John Ousterhout, en "A Philosophy of Software Design", argumenta que este enfoque produce "shallow modules". \xbfEn qu\xe9 consiste su cr\xedtica y qu\xe9 evidencia emp\xedrica existe a favor y en contra de las funciones peque\xf1as?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),': John Ousterhout (Stanford, 2018) argumenta que el fanatismo por funciones peque\xf1as produce "shallow modules": funciones cuya interfaz (firma, par\xe1metros, contrato conceptual) es casi tan compleja como su implementaci\xf3n. Su ejemplo: si part\xeds una funci\xf3n de 90 l\xedneas en 9 funciones de 10 l\xedneas, el lector ahora debe navegar 9 funciones para entender el flujo completo, y la complejidad TOTAL del sistema (medida como el costo de entender la interacci\xf3n entre las 9 funciones) puede ser MAYOR que la complejidad de la funci\xf3n original. La m\xe9trica de Ousterhout es la "profundidad": una buena abstracci\xf3n tiene una interfaz SIMPLE y una implementaci\xf3n COMPLEJA. A favor de funciones peque\xf1as: estudio de Herraiz & Hassan (2010) encontr\xf3 que archivos con funciones peque\xf1as (< 20 LOC) tienen menor densidad de bugs. En contra: estudio de Syer et al. (2012) en Android apps no encontr\xf3 correlaci\xf3n entre longitud de m\xe9todo y defectos una vez que se controla por complejidad ciclom\xe1tica \u2014sugiriendo que la longitud es un proxy ruidoso.']}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),': La clase toma partido absoluto por funciones peque\xf1as sin presentar la discusi\xf3n acad\xe9mica. Ousterhout ense\xf1a un curso de dise\xf1o de software en Stanford y su libro es contrapunto directo a Clean Code en varias dimensiones. El alumno debe entender que "funciones peque\xf1as" es una heur\xedstica, no una ley, y que el objetivo real es BAJA COMPLEJIDAD por funci\xf3n, que puede lograrse con funciones m\xe1s largas si son inherentemente simples (secuenciales, sin ramas).']}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsxs)(a.h3,{id:"9-cuestionar-el-principio-command-query-separation-dice-que-un-m\xe9todo-debe-ser-comando-o-consulta-sin-embargo-operaciones-como-stackpop-que-devuelve-el-elemento-y-modifica-el-stack-son-ubicuas-en-la-pr\xe1ctica-es-pop-un-mal-dise\xf1o-qu\xe9-dice-bertrand-meyer-creador-de-cqs-sobre-este-tipo-de-excepciones",children:['9. [Cuestionar] El principio "Command Query Separation" dice que un m\xe9todo debe ser comando o consulta. Sin embargo, operaciones como ',(0,s.jsx)(a.code,{children:"stack.pop()"})," \u2014que devuelve el elemento y modifica el stack\u2014 son ubicuas en la pr\xe1ctica. \xbfEs ",(0,s.jsx)(a.code,{children:"pop()"})," un mal dise\xf1o? \xbfQu\xe9 dice Bertrand Meyer (creador de CQS) sobre este tipo de excepciones?"]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),": ",(0,s.jsx)(a.code,{children:"pop()"}),' es universalmente aceptado, pero Bertrand Meyer, creador de CQS, reconoce que ciertas operaciones son inherentemente "hybrid" y que CQS es un principio de dise\xf1o, no una regla inquebrantable. En el libro "Object-Oriented Software Construction" (1988, 2da edici\xf3n 1997), Meyer admite que ',(0,s.jsx)(a.code,{children:"pop()"})," viola CQS porque modifica el stack (comando) Y devuelve el elemento (consulta). Sin embargo, Meyer argumenta que esta violaci\xf3n es pragm\xe1tica porque: (a) separar en ",(0,s.jsx)(a.code,{children:"top()"})," + ",(0,s.jsx)(a.code,{children:"remove()"})," crea una condici\xf3n de carrera en entornos multithread, (b) la operaci\xf3n es tan primitiva y universalmente comprendida que el riesgo de confusi\xf3n es m\xednimo, (c) el lenguaje Eiffel (de Meyer) provee el modificador ",(0,s.jsx)(a.code,{children:"obsolete"})," para advertir al llamante. La posici\xf3n moderna sobre CQS es: es un principio que debe seguirse por defecto, con excepciones JUSTIFICADAS y DOCUMENTADAS. Si tu sistema tiene 3 violaciones documentadas de CQS en 500 m\xe9todos, es excelente dise\xf1o. Si tiene 50 violaciones sin documentar, es desorden."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),": La clase presenta CQS de manera absoluta. El propio Meyer \u2014creador del principio\u2014 es m\xe1s pragm\xe1tico. El alumno debe entender que los principios de dise\xf1o son herramientas de juicio, no mandamientos. La discusi\xf3n de ",(0,s.jsx)(a.code,{children:"pop()"})," es el ejemplo can\xf3nico en la comunidad para distinguir entre pureza te\xf3rica y pragmatismo ingenieril."]}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h3,{id:"10-cuestionar-extraer-hasta-que-no-puedas-extraer-m\xe1s-es-una-filosof\xeda-de-refactorizaci\xf3n-atribuida-a-robert-c-martin-qu\xe9-l\xedmites-identifica-sandi-metz-99-bottles-of-oop-al-extract-method-agresivo-c\xf3mo-determina-ella-cu\xe1ndo-una-extracci\xf3n-est\xe1-creando-una-abstracci\xf3n-equivocada",children:'10. [Cuestionar] "Extraer hasta que no puedas extraer m\xe1s" es una filosof\xeda de refactorizaci\xf3n atribuida a Robert C. Martin. \xbfQu\xe9 l\xedmites identifica Sandi Metz ("99 Bottles of OOP") al "extract method" agresivo? \xbfC\xf3mo determina ella cu\xe1ndo una extracci\xf3n est\xe1 creando una abstracci\xf3n equivocada?'}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Respuesta"}),': Sandi Metz, en "99 Bottles of OOP" (2016, co-escrito con Katrina Owen), argumenta que la extracci\xf3n agresiva de m\xe9todos sin un criterio sem\xe1ntico produce el anti-patr\xf3n de "abstracciones equivocadas" (wrong abstractions), que considera m\xe1s costoso que la duplicaci\xf3n. Su tesis: "la duplicaci\xf3n es m\xe1s barata que la abstracci\xf3n incorrecta". Metz propone el criterio de "squint test" (entrecerrar los ojos): si dos fragmentos de c\xf3digo se ven iguales cuando entrecerr\xe1s los ojos (misma forma, mismas variables, mismo patr\xf3n), pueden ser la misma abstracci\xf3n. Si requieren par\xe1metros booleanos (',(0,s.jsx)(a.code,{children:"extractedMethod(flag = true)"}),") o m\xfaltiples sobrecargas para cubrir variaciones sutiles, la abstracci\xf3n es prematura \u2014esper\xe1 a tener 3 o m\xe1s ocurrencias ANTES de extraer. La regla derivada: no extraigas en el primer o segundo uso repetido; extra\xe9 cuando el patr\xf3n sea INEQU\xcdVOCO."]}),"\n",(0,s.jsxs)(a.p,{children:[(0,s.jsx)(a.strong,{children:"Por qu\xe9"}),': La clase promueve la extracci\xf3n como virtud sin advertir sobre la abstracci\xf3n prematura. Metz es una de las voces m\xe1s influyentes en dise\xf1o OOP moderno y su libro "99 Bottles" es usado como material complementario en cursos de refactoring. El alumno debe desarrollar criterio sobre CU\xc1NDO extraer \u2014no asumir que extraer siempre es bueno. Esta es quiz\xe1s la lecci\xf3n m\xe1s importante que Clean Code por s\xed solo no ense\xf1a.']})]})}function u(e={}){const{wrapper:a}={...(0,r.R)(),...e.components};return a?(0,s.jsx)(a,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},28453(e,a,o){o.d(a,{R:()=>i,x:()=>c});var n=o(96540);const s={},r=n.createContext(s);function i(e){const a=n.useContext(r);return n.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function c(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:i(e.components),n.createElement(r.Provider,{value:a},e.children)}}}]);